import Anthropic from "@anthropic-ai/sdk";

const ALLOWED_HOSTS = new Set(["developer.mozilla.org", "docs.python.org"]);
const NEEDS_HUMAN = new Set(["send_email", "delete_file"]);

function canFetch(url: string): boolean {
  const { protocol, hostname } = new URL(url);
  return protocol === "https:" && ALLOWED_HOSTS.has(hostname);
}

// Вызывается в tool-use петле для каждого блока tool_use из ответа модели
async function runTool(
  block: Anthropic.ToolUseBlock,
  confirm: (b: Anthropic.ToolUseBlock) => Promise<boolean>,
): Promise<Anthropic.ToolResultBlockParam> {
  // 1. Разрушительное: только после явного «да» человека
  if (NEEDS_HUMAN.has(block.name) && !(await confirm(block))) {
    return { type: "tool_result", tool_use_id: block.id, is_error: true,
      content: JSON.stringify({ error: "user declined" }) };
  }
  if (block.name === "fetch_page") {
    const { url } = block.input as { url: string };
    // 2. Куда можно ходить, решает код, а не модель
    if (!canFetch(url)) {
      return { type: "tool_result", tool_use_id: block.id, is_error: true,
        content: JSON.stringify({ error: "host not allowed", url }) };
    }
    const text = await (await fetch(url)).text();
    // 3. Чужой текст: только в tool_result и только как JSON-строка
    return { type: "tool_result", tool_use_id: block.id,
      content: JSON.stringify({ url, text }) };
  }
  return { type: "tool_result", tool_use_id: block.id, is_error: true,
    content: JSON.stringify({ error: "unknown tool" }) };
}

